      "tipo": "GC",
      "causa_raiz": "Concatenacao iterativa de strings com operador '+' e alocacao repetida de arrays dentro do Update(), gerando mais de 5.1 MB de lixo por frame e provocando paradas do Garbage Collector de 22.75 ms, estourando o budget de 16.7 ms por frame.",
      "codigo_refatorado": "using System;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n        public GameObject testPrefab;\\n        [Range(1, 20)] public float spawnRadius = 10f;\\n        [Range(1, 50)] public int cubesPerFrame = 1;\\n        public bool useUniqueMaterials = false;\\n        [Range(1, 512)] public int cpuScansPerFrame = 1;\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n        [Range(0, 2000)] public int prepopulateCount = 0;\\n\\n        private readonly StringBuilder _stringCache = new StringBuilder(4096);\\n        private MaterialPropertyBlock _propBlock;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\\\"_Color\\\");\\n\\n        private void Awake()\\n        {\\n            _propBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                new GameObject(\\\"Empty_\\\" + i);\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                Destroy(quad.GetComponent<Collider>());\\n                quad.name = \\\"Overdraw_\\\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _stringCache.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _stringCache.Append(i);\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);\\n            if (useUniqueMaterials && clone.TryGetComponent<Renderer>(out var rend))\\n            {\\n                rend.GetPropertyBlock(_propBlock);\\n                _propBlock.SetColor(ColorPropertyId, UnityEngine.Random.ColorHSV());\\n                rend.SetPropertyBlock(_propBlock);\\n            }\\n        }\\n    }\\n}",
      "explicacao_didatica": "Strings sao imutaveis em C#. Toda vez que voce usa '+' dentro de um loop, a Unity cria uma nova copia na memoria e joga a antiga fora. Com milhares de repeticoes por frame, a memoria enche rapidamente e o Garbage Collector interrompe o jogo para fazer a limpeza, causando travamentos bruscos. Usar StringBuilder e evitar instanciar novos objetos dentro do Update elimina esse lixo."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Execucao repetida de 'GameObject.FindObjectsOfType<GameObject>()' dentro de Update(), realizando varreduras lineares completas em toda a hierarquia de objetos e alocando arrays gerenciados repetidamente, elevando o tempo de CPU para ate 125.67 ms.",
      "codigo_refatorado": "// Para otimizar a CPU, remova buscas globais como FindObjectsOfType ou Find do Update.\\n// Caso precise rastrear objetos, faca isso armazenando referencias em listas gerenciadas no Awake/Start\\n// ou usando padroes de registro direto (Registration Pattern / Dependency Injection).\\n\\n// Trecho removido do Update:\\n// for (int k = 0; k < cpuScansPerFrame; k++)\\n// {\\n//     var allObjects = GameObject.FindObjectsOfType<GameObject>();\\n//     GC.KeepAlive(allObjects);\\n// }",
      "explicacao_didatica": "A funcao FindObjectsOfType varre cada objeto existente na cena para verificar o tipo. Fazer essa busca repetidas vezes a cada frame sobrecarrega terrivelmente o processador e aloca vetores na memoria. O ideal e guardar uma referencia direta do objeto quando ele for criado ou registrar em uma lista centralizada."
    }
  ],
  "dicas_level_design": null
}

